insert into support_resources (id, title, category, summary, body, source_label, published)
values
  ('resource-care-coordination', 'Coordinating care across specialists', 'appointments', 'Keep the names and contact details of the professionals involved in your care.', 'Write down the name, specialty, clinic, and contact method for each professional involved in your care. Ask who coordinates your overall treatment plan and where test results should be sent. Keep a copy of key letters and ask how to share updates between your oncology team, primary-care clinician, and other specialists.', 'CancerCompanion educational content', true),
  ('resource-financial-support', 'Talking about treatment-related costs', 'resources', 'Financial and practical support may be available through hospitals and community organizations.', 'Ask the hospital social worker or patient navigator whether financial counselling, transport assistance, medication support, accommodation help, or community programs are available. Before sharing financial information, confirm that you are speaking with an official service. Be cautious of unsolicited requests for payment or personal details.', 'CancerCompanion educational content', true),
  ('resource-caregiver-wellbeing', 'Supporting the wellbeing of caregivers', 'caregivers', 'Caregivers also need rest, support, and clear communication.', 'Agree on practical tasks and a schedule that can be shared among trusted people. Encourage caregivers to take breaks and seek support when they feel overwhelmed. Discuss boundaries, privacy, and which updates the patient wants shared. Contact the care team or local support services when caregiver stress becomes difficult to manage.', 'CancerCompanion educational content', true)
